<?php
require_once __DIR__.'/../includes/bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['product_id']??0);$action=$_POST['action']??'';if($action==='add'){$qty=max(1,min(10,(int)($_POST['quantity']??1)));$st=$pdo->prepare("SELECT product_id FROM products WHERE product_id=? AND status='active' AND stock>=?");$st->execute([$id,$qty]);if($st->fetch()) {$_SESSION['cart'][$id]=min(10,(int)($_SESSION['cart'][$id]??0)+$qty);$_SESSION['cart_variants'][$id]=['size'=>trim($_POST['size']??'M')?:'M','color'=>trim($_POST['color']??'Natural')?:'Natural'];flash('Added to your cart.');}else flash('Product unavailable or stock too low.');}elseif($action==='remove'){unset($_SESSION['cart'][$id],$_SESSION['cart_variants'][$id]);}elseif($action==='quantity'){$_SESSION['cart'][$id]=max(1,min(10,(int)($_POST['quantity']??1)));}header('Location: cart.php');exit;}
$cart=$_SESSION['cart']??[];$rows=[];$subtotal=0;if($cart){$ids=array_map('intval',array_keys($cart));$marks=implode(',',array_fill(0,count($ids),'?'));$st=$pdo->prepare("SELECT product_id,title,price,image_url FROM products WHERE product_id IN ($marks)");$st->execute($ids);$rows=$st->fetchAll();}
$pageTitle='Your cart | Redline Royale';$pageClass='cart-page';include __DIR__.'/../includes/header.php';$count=array_sum($cart);
?>
<div class="page-kicker">SHOPPING CART</div><h1 class="page-heading">Your cart · <?=$count?> <?=($count===1?'item':'items')?></h1><?php if(!$rows):?><section class="empty-cart"><p>Your cart is empty.</p><a class="primary-link" href="index.php">Browse clothing</a></section><?php else:?><div class="cart-layout"><section class="cart-items"><?php foreach($rows as $p):$qty=(int)$cart[$p['product_id']];$subtotal+=$qty*(float)$p['price'];$variant=$_SESSION['cart_variants'][$p['product_id']]??['color'=>'Natural','size'=>'M'];?><article class="cart-item"><img src="<?=e(asset_url(product_image_url($p)))?>" alt="<?=e($p['title'])?>"><div><h2><?=e($p['title'])?> · <?=e($variant['color'])?> · <?=e($variant['size'])?></h2><p class="price">Rs. <?=number_format((float)$p['price'],2)?></p><div class="cart-actions"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="quantity"><input type="hidden" name="product_id" value="<?=$p['product_id']?>"><button name="quantity" value="<?=max(1,$qty-1)?>" aria-label="Decrease quantity">−</button><span><?=$qty?></span><button name="quantity" value="<?=$qty+1?>" aria-label="Increase quantity">+</button></form><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?=$p['product_id']?>"><button class="text-button">Remove</button></form></div></div></article><?php endforeach;?></section><aside class="order-summary"><h2>Order summary</h2><p><span>Subtotal</span><strong>Rs. <?=number_format($subtotal,2)?></strong></p><p><span>Delivery</span><span>Rs. 150.00 · free on collection</span></p><p class="summary-total"><strong>Total</strong><strong>Rs. <?=number_format($subtotal+150,2)?></strong></p><small>Cash on delivery or cash on collection — the delivery fee is removed at checkout for collection orders.</small><a class="primary-link" href="checkout.php">Proceed to checkout</a></aside></div><?php endif;?>
<?php include __DIR__.'/../includes/footer.php';?>
